(window.ABDI_PAKET = window.ABDI_PAKET || {})["skd.tkp.profesionalisme.1"] = [{"i":2710,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Atasan memberi tugas mendesak saat Anda masih menyelesaikan tugas lain. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menyusun prioritas, menyampaikan perkiraan waktu kepada atasan, dan menyelesaikan keduanya.” Mengelola prioritas dan berkomunikasi.\nPilihan terendah (nilai 1): “Mengabaikan tugas mendesak karena tugas lama belum selesai.” Mengabaikan perintah kerja.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Menanyakan kepada atasan tugas mana yang harus didahulukan.","Meminta tugas mendesak itu diberikan kepada rekan lain.","Mengabaikan tugas mendesak karena tugas lama belum selesai.","Menyusun prioritas, menyampaikan perkiraan waktu kepada atasan, dan menyelesaikan keduanya.","Mengerjakan tugas mendesak lebih dulu, lalu melanjutkan tugas sebelumnya."],"s":[3,2,1,5,4],"w":["Bergantung pada arahan.","Menghindari tugas.","Mengabaikan perintah kerja.","Mengelola prioritas dan berkomunikasi.","Tepat, tetapi tanpa komunikasi."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":2711,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda menyadari ada kesalahan dalam laporan yang sudah Anda serahkan kepada atasan. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Segera memberi tahu atasan, memperbaiki laporan, dan memeriksa ulang bagian lainnya.” Jujur, bertanggung jawab, dan teliti.\nPilihan terendah (nilai 1): “Menyalahkan rekan yang memberi data.” Melempar kesalahan.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Memperbaikinya diam-diam pada laporan berikutnya.","Memperbaiki laporan dan menyerahkannya kembali.","Menunggu atasan menemukan kesalahan itu.","Menyalahkan rekan yang memberi data.","Segera memberi tahu atasan, memperbaiki laporan, dan memeriksa ulang bagian lainnya."],"s":[3,4,2,1,5],"w":["Tidak transparan.","Bertanggung jawab, tetapi kurang terbuka.","Menghindari tanggung jawab.","Melempar kesalahan.","Jujur, bertanggung jawab, dan teliti."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":2712,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda ditawari hadiah oleh vendor yang sedang mengikuti pengadaan di kantor Anda. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menolak hadiah dengan sopan dan melaporkannya sesuai aturan gratifikasi.” Integritas penuh dan patuh aturan.\nPilihan terendah (nilai 1): “Menerima hadiah dan membantu vendor itu menang.” Korupsi.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Menolak hadiah tersebut.","Menerima hadiah asalkan nilainya kecil.","Menerima hadiah dan membantu vendor itu menang.","Menolak hadiah dengan sopan dan melaporkannya sesuai aturan gratifikasi.","Menanyakan kepada rekan apakah hadiah itu boleh diterima."],"s":[4,2,1,5,3],"w":["Menolak, tanpa pelaporan.","Tetap gratifikasi.","Korupsi.","Integritas penuh dan patuh aturan.","Ragu-ragu."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":2713,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda diminta lembur untuk menyelesaikan laporan akhir tahun. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menyelesaikan laporan dengan teliti dan mengatur waktu agar target tercapai.” Bertanggung jawab atas hasil.\nPilihan terendah (nilai 1): “Menolak lembur dan meninggalkan pekerjaan.” Meninggalkan tanggung jawab.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Menyelesaikan laporan dengan teliti dan mengatur waktu agar target tercapai.","Bersedia lembur jika ada insentif tambahan.","Mengerjakan seadanya agar bisa cepat pulang.","Bersedia lembur sesuai jadwal yang ditentukan.","Menolak lembur dan meninggalkan pekerjaan."],"s":[5,3,2,4,1],"w":["Bertanggung jawab atas hasil.","Bersyarat.","Mengorbankan mutu.","Patuh.","Meninggalkan tanggung jawab."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":2714,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Seorang rekan meminta Anda mengisi daftar hadir untuknya karena ia datang terlambat. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menolak dengan baik dan menyarankannya mengikuti prosedur keterlambatan yang berlaku.” Jujur dan memberi solusi.\nPilihan terendah (nilai 1): “Mengisinya dan menawarkan diri untuk melakukannya lagi.” Kecurangan berulang.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Mengisinya dan menawarkan diri untuk melakukannya lagi.","Menolak permintaan tersebut.","Mengisinya kali ini saja.","Menolak dengan baik dan menyarankannya mengikuti prosedur keterlambatan yang berlaku.","Mengatakan bahwa Anda tidak berani melakukannya."],"s":[1,4,2,5,3],"w":["Kecurangan berulang.","Jujur.","Kecurangan.","Jujur dan memberi solusi.","Menolak, tetapi bukan karena prinsip."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":2715,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda mendapat tugas di luar keahlian Anda. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mempelajari hal yang diperlukan, berkonsultasi dengan yang ahli, dan menyelesaikan tugas dengan baik.” Mau belajar dan tuntas.\nPilihan terendah (nilai 1): “Menolak tugas karena bukan bidang Anda.” Menolak tugas.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Mempelajari hal yang diperlukan, berkonsultasi dengan yang ahli, dan menyelesaikan tugas dengan baik.","Mengerjakan sesuai contoh tugas sebelumnya.","Meminta tugas itu dialihkan kepada orang lain.","Mengerjakan sebisanya dan meminta masukan atasan.","Menolak tugas karena bukan bidang Anda."],"s":[5,3,2,4,1],"w":["Mau belajar dan tuntas.","Kurang inisiatif.","Menghindar.","Berusaha.","Menolak tugas."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":2716,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Menurut Anda, kebijakan baru dari atasan kurang tepat. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menyampaikan masukan secara sopan dengan data melalui forum yang tepat, lalu tetap menjalankan keputusan akhir.” Kritis secara membangun dan tetap loyal.\nPilihan terendah (nilai 1): “Sengaja tidak menjalankan kebijakan tersebut.” Membangkang.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Menyampaikan masukan secara sopan dengan data melalui forum yang tepat, lalu tetap menjalankan keputusan akhir.","Menjalankan kebijakan tanpa memberi masukan.","Mengeluhkan kebijakan itu kepada rekan-rekan.","Menjalankan kebijakan sambil mencatat kendala untuk dilaporkan.","Sengaja tidak menjalankan kebijakan tersebut."],"s":[5,3,2,4,1],"w":["Kritis secara membangun dan tetap loyal.","Pasif.","Tidak membangun.","Baik, tetapi masukannya tertunda.","Membangkang."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":2717,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Pekerjaan Anda sudah selesai sebelum jam kerja berakhir. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Memeriksa ulang hasil kerja, lalu membantu rekan atau menyiapkan tugas berikutnya.” Memanfaatkan waktu secara produktif.\nPilihan terendah (nilai 1): “Pulang lebih awal tanpa izin.” Melanggar disiplin.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Pulang lebih awal tanpa izin.","Memeriksa ulang hasil kerja, lalu membantu rekan atau menyiapkan tugas berikutnya.","Memeriksa ulang hasil kerja Anda.","Mengisi waktu dengan bermain gawai.","Menunggu tugas baru dari atasan."],"s":[1,5,4,2,3],"w":["Melanggar disiplin.","Memanfaatkan waktu secara produktif.","Teliti.","Tidak produktif.","Pasif."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":2718,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda menemukan rekan memanipulasi data capaian kinerja agar terlihat baik. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengingatkannya untuk memperbaiki data, dan melaporkannya sesuai mekanisme jika ia tidak mau.” Mengutamakan perbaikan dan tetap tegas.\nPilihan terendah (nilai 1): “Ikut memanipulasi data unit Anda agar tidak kalah.” Ikut melanggar.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Melaporkan temuan itu kepada atasan sesuai mekanisme.","Mengingatkannya untuk memperbaiki data, dan melaporkannya sesuai mekanisme jika ia tidak mau.","Ikut memanipulasi data unit Anda agar tidak kalah.","Mengingatkannya, tetapi membiarkan jika ia tidak mau memperbaiki.","Pura-pura tidak tahu."],"s":[4,5,1,3,2],"w":["Tegas, tanpa pendekatan.","Mengutamakan perbaikan dan tetap tegas.","Ikut melanggar.","Tidak tuntas.","Membiarkan pelanggaran."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3184,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda menyadari target pekerjaan bulan ini tidak akan tercapai tepat waktu. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Memberi tahu atasan sejak dini beserta penyebab dan rencana pemulihannya.” Terbuka dan bertanggung jawab.\nPilihan terendah (nilai 1): “Melaporkan capaian yang lebih tinggi dari kenyataan.” Tidak jujur.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Lembur setiap hari tanpa memberi tahu atasan, dengan harapan target tetap bisa dikejar sendiri sebelum akhir bulan.","Menunggu atasan bertanya.","Menunda melapor sampai tenggat lewat.","Melaporkan capaian yang lebih tinggi dari kenyataan.","Memberi tahu atasan sejak dini beserta penyebab dan rencana pemulihannya."],"s":[4,3,2,1,5],"w":["Berusaha keras, tetapi tidak terbuka.","Pasif.","Menghindar.","Tidak jujur.","Terbuka dan bertanggung jawab."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3185,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Atasan memuji pekerjaan yang sebenarnya dikerjakan oleh rekan Anda. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menjelaskan kepada atasan bahwa pekerjaan itu hasil kerja rekan Anda.” Jujur dan menghargai rekan.\nPilihan terendah (nilai 1): “Menerima pujian itu sebagai hasil kerja Anda.” Tidak jujur.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Menerima pujian itu sebagai hasil kerja Anda.","Menghindari bertemu atasan supaya tidak dibahas lagi.","Menjelaskan kepada atasan bahwa pekerjaan itu hasil kerja rekan Anda.","Berterima kasih atas pujian itu lalu menceritakannya kepada rekan tersebut supaya ia tahu hasil kerjanya diapresiasi pimpinan.","Diam saja."],"s":[1,2,5,4,3],"w":["Tidak jujur.","Menghindar.","Jujur dan menghargai rekan.","Menghargai rekan, tetapi atasan tetap keliru.","Pasif."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3186,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Menjelang pemilihan kepala daerah, seorang calon mengajak Anda hadir di acara kampanyenya. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menolak dengan sopan karena ASN wajib netral, dan tetap menjaga hubungan baik.” Menjaga netralitas ASN.\nPilihan terendah (nilai 1): “Hadir dan ikut mengajak rekan kantor mendukung calon itu karena programnya dianggap bagus untuk daerah dan ia kenalan lama keluarga.” Melanggar netralitas ASN.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Hadir dan ikut mengajak rekan kantor mendukung calon itu karena programnya dianggap bagus untuk daerah dan ia kenalan lama keluarga.","Menolak dengan sopan karena ASN wajib netral, dan tetap menjaga hubungan baik.","Menolak ajakan itu.","Mengatakan akan memikirkannya.","Hadir sebentar tanpa memakai atribut."],"s":[1,5,4,2,3],"w":["Melanggar netralitas ASN.","Menjaga netralitas ASN.","Netral.","Tidak tegas.","Melanggar netralitas secara halus."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3187,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda diminta menyusun laporan pertanggungjawaban perjalanan dinas dengan jumlah hari lebih banyak dari yang sebenarnya. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menolak dan menyusun laporan sesuai jumlah hari yang sebenarnya.” Jujur dan akuntabel.\nPilihan terendah (nilai 1): “Menyusun laporan sesuai permintaan karena katanya sudah menjadi kebiasaan dan selisihnya dipakai untuk kegiatan unit.” Memalsukan pertanggungjawaban.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Meminta waktu untuk berpikir.","Menolak dan menjelaskan risikonya kepada yang meminta.","Menyusun laporan sesuai permintaan karena katanya sudah menjadi kebiasaan dan selisihnya dipakai untuk kegiatan unit.","Menghindari tugas penyusunan laporan itu.","Menolak dan menyusun laporan sesuai jumlah hari yang sebenarnya."],"s":[3,4,1,2,5],"w":["Ragu.","Jujur.","Memalsukan pertanggungjawaban.","Menghindar.","Jujur dan akuntabel."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3188,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda sakit ringan, sementara hari itu ada tugas penting. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Memberi tahu atasan dan mengatur penyelesaian tugas penting itu, misalnya dengan menyerahkan bahan kepada rekan atau bekerja dari rumah bila diizinkan.” Bertanggung jawab.\nPilihan terendah (nilai 1): “Meminta rekan mengisi daftar hadir Anda.” Tidak jujur.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Tidak masuk tanpa kabar.","Meminta rekan mengisi daftar hadir Anda.","Tidak masuk dan menunggu dihubungi.","Memberi tahu atasan dan mengatur penyelesaian tugas penting itu, misalnya dengan menyerahkan bahan kepada rekan atau bekerja dari rumah bila diizinkan.","Tetap masuk kerja walaupun kurang sehat."],"s":[2,1,3,5,4],"w":["Lalai.","Tidak jujur.","Pasif.","Bertanggung jawab.","Berdedikasi, berisiko."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3189,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Seorang rekan meminta Anda memberinya nilai kinerja tinggi dalam penilaian sesama rekan karena kalian berteman. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menilai sesuai kinerja sebenarnya dan menjelaskan bahwa penilaian harus objektif.” Objektif.\nPilihan terendah (nilai 1): “Memberinya nilai tertinggi karena ia sahabat Anda dan nilai itu tidak memengaruhi siapa pun secara langsung.” Tidak objektif.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Menilai secara objektif tanpa memberi tahu siapa pun.","Memberinya nilai tertinggi karena ia sahabat Anda dan nilai itu tidak memengaruhi siapa pun secara langsung.","Memberi nilai rata-rata untuk semua orang.","Menghindari pengisian penilaian.","Menilai sesuai kinerja sebenarnya dan menjelaskan bahwa penilaian harus objektif."],"s":[4,1,3,2,5],"w":["Objektif, kurang komunikatif.","Tidak objektif.","Tidak objektif.","Menghindar.","Objektif."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3190,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda mendapat kesempatan mengikuti pelatihan, tetapi jadwalnya bersamaan dengan pekerjaan rutin. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengikuti pelatihan setelah mengatur penyelesaian pekerjaan rutin bersama atasan dan rekan.” Belajar tanpa mengabaikan tugas.\nPilihan terendah (nilai 1): “Mengikuti pelatihan dan membiarkan pekerjaan rutin terbengkalai.” Mengabaikan tugas.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Mengikuti pelatihan dan membiarkan pekerjaan rutin terbengkalai.","Mengikuti pelatihan dan menyelesaikan pekerjaan rutin setelah pulang dari pelatihan setiap hari, walaupun harus lembur sampai malam.","Mengikuti pelatihan setelah mengatur penyelesaian pekerjaan rutin bersama atasan dan rekan.","Meminta atasan memutuskan.","Menolak pelatihan karena repot."],"s":[1,4,5,3,2],"w":["Mengabaikan tugas.","Berkomitmen, berisiko kelelahan.","Belajar tanpa mengabaikan tugas.","Pasif.","Menutup peluang."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3191,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Atasan memberi tugas yang menurut Anda melanggar aturan. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menyampaikan keberatan dengan sopan beserta dasar aturannya, dan menawarkan cara lain yang sesuai.” Tegas pada aturan dan solutif.\nPilihan terendah (nilai 1): “Melaksanakannya karena perintah atasan harus dipatuhi dan tanggung jawabnya ada pada atasan, bukan pada Anda.” Ikut melanggar aturan.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Menolak tugas itu dengan sopan.","Menyampaikan keberatan dengan sopan beserta dasar aturannya, dan menawarkan cara lain yang sesuai.","Melaksanakannya karena perintah atasan harus dipatuhi dan tanggung jawabnya ada pada atasan, bukan pada Anda.","Menunda pelaksanaan sambil menunggu atasan berubah pikiran.","Meminta rekan lain mengerjakannya."],"s":[4,5,1,3,2],"w":["Tegas.","Tegas pada aturan dan solutif.","Ikut melanggar aturan.","Menghindar.","Melempar."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3192,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda harus memilih antara menyelesaikan tugas dengan cepat atau dengan teliti. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Membahas dengan atasan bagian mana yang paling penting, lalu menyelesaikannya dengan teliti dalam waktu yang disepakati.” Seimbang dan terencana.\nPilihan terendah (nilai 1): “Menyelesaikan cepat dengan menyalin pekerjaan lama tanpa diperiksa, karena atasan biasanya hanya melihat apakah tugas selesai tepat waktu.” Asal jadi.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Menyelesaikan cepat dengan menyalin pekerjaan lama tanpa diperiksa, karena atasan biasanya hanya melihat apakah tugas selesai tepat waktu.","Mengerjakan sebisanya.","Membahas dengan atasan bagian mana yang paling penting, lalu menyelesaikannya dengan teliti dalam waktu yang disepakati.","Menunda sampai mendekati tenggat.","Mengutamakan ketelitian walaupun sedikit terlambat."],"s":[1,3,5,2,4],"w":["Asal jadi.","Pasif.","Seimbang dan terencana.","Menunda.","Berkualitas."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3193,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Hasil kerja Anda dikritik keras oleh atasan di depan rekan-rekan. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menerima kritik dengan tenang, menanyakan bagian yang perlu diperbaiki, dan memperbaikinya.” Dewasa dan mau belajar.\nPilihan terendah (nilai 1): “Membalas kritik dengan nada tinggi dan menyebutkan kesalahan atasan di depan rekan-rekan supaya ia tahu rasanya dipermalukan.” Tidak profesional.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Menerima kritik dengan tenang, menanyakan bagian yang perlu diperbaiki, dan memperbaikinya.","Diam dan memendam rasa kesal.","Menghindari atasan beberapa hari.","Membalas kritik dengan nada tinggi dan menyebutkan kesalahan atasan di depan rekan-rekan supaya ia tahu rasanya dipermalukan.","Menerima kritik dan memperbaiki pekerjaan."],"s":[5,3,2,1,4],"w":["Dewasa dan mau belajar.","Pasif.","Menghindar.","Tidak profesional.","Profesional."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3194,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda mengetahui kerabat Anda ikut tender di instansi Anda, sementara Anda termasuk panitia. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Melaporkan konflik kepentingan itu kepada atasan dan mengundurkan diri dari penilaian tender tersebut.” Mencegah konflik kepentingan.\nPilihan terendah (nilai 1): “Membantu kerabat menang tender karena penawarannya toh tidak terlalu jauh dari peserta lain.” Kolusi.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Melaporkan konflik kepentingan itu kepada atasan dan mengundurkan diri dari penilaian tender tersebut.","Membantu kerabat menang tender karena penawarannya toh tidak terlalu jauh dari peserta lain.","Tidak hadir saat rapat penilaian.","Bersikap netral tanpa memberi tahu siapa pun.","Menunggu sampai ada yang bertanya."],"s":[5,1,2,4,3],"w":["Mencegah konflik kepentingan.","Kolusi.","Menghindar.","Berniat baik, tidak transparan.","Pasif."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3195,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda memakai kendaraan dinas, dan keluarga meminta diantar ke acara pribadi. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menolak dan menjelaskan bahwa kendaraan dinas hanya untuk keperluan dinas.” Menjaga aset negara.\nPilihan terendah (nilai 1): “Mengantar keluarga dan memakai bahan bakar kendaraan dinas, karena acara itu penting dan jaraknya tidak terlalu jauh dari kantor.” Penyalahgunaan aset.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Menolak dan menawarkan mengantar dengan kendaraan pribadi.","Menolak dan menjelaskan bahwa kendaraan dinas hanya untuk keperluan dinas.","Mengatakan kendaraannya sedang dipakai.","Mengantar keluarga dan memakai bahan bakar kendaraan dinas, karena acara itu penting dan jaraknya tidak terlalu jauh dari kantor.","Mengantar sebentar karena searah."],"s":[4,5,2,1,3],"w":["Tepat.","Menjaga aset negara.","Tidak jujur.","Penyalahgunaan aset.","Melanggar secara halus."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3196,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda menemukan anggaran kegiatan masih tersisa banyak menjelang akhir tahun. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Melaporkan sisa anggaran apa adanya dan mengusulkan pemanfaatan atau pengembalian sesuai aturan.” Akuntabel.\nPilihan terendah (nilai 1): “Mengadakan kegiatan tambahan yang tidak perlu supaya anggaran terserap habis dan unit tidak dianggap gagal merencanakan.” Pemborosan.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Mengadakan kegiatan tambahan yang tidak perlu supaya anggaran terserap habis dan unit tidak dianggap gagal merencanakan.","Melaporkan sisa anggaran apa adanya dan mengusulkan pemanfaatan atau pengembalian sesuai aturan.","Melaporkan sisa anggaran kepada atasan.","Menunda pelaporan.","Membiarkannya sampai ada arahan."],"s":[1,5,4,2,3],"w":["Pemborosan.","Akuntabel.","Jujur.","Menunda.","Pasif."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3197,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Atasan sedang cuti, dan ada keputusan mendesak yang sebenarnya masih dalam wewenang Anda. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengambil keputusan sesuai wewenang dan aturan, mendokumentasikannya, lalu melaporkannya kepada atasan.” Bertanggung jawab.\nPilihan terendah (nilai 1): “Mengambil keputusan di luar wewenang Anda supaya terlihat tegas.” Melampaui wewenang.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Menghubungi atasan yang sedang cuti untuk meminta pendapat sebelum memutuskan, walaupun keputusan itu sebenarnya wewenang Anda sendiri.","Mengambil keputusan sesuai wewenang dan aturan, mendokumentasikannya, lalu melaporkannya kepada atasan.","Menunggu atasan kembali.","Melempar keputusan kepada rekan lain.","Mengambil keputusan di luar wewenang Anda supaya terlihat tegas."],"s":[4,5,3,2,1],"w":["Hati-hati, tetapi mengganggu dan lambat.","Bertanggung jawab.","Pasif.","Menghindar.","Melampaui wewenang."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3198,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda merasa kelelahan karena beban kerja terus meningkat. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menyampaikan kondisi beban kerja kepada atasan dengan data, dan mengusulkan pengaturan prioritas atau pembagian tugas.” Terbuka dan solutif.\nPilihan terendah (nilai 1): “Menyelesaikan pekerjaan secara asal supaya cepat selesai, karena menurut Anda kualitas tidak terlalu diperhatikan atasan.” Menurunkan kualitas.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Mengatur ulang jadwal kerja sendiri supaya lebih efisien.","Menyampaikan kondisi beban kerja kepada atasan dengan data, dan mengusulkan pengaturan prioritas atau pembagian tugas.","Terus bekerja tanpa bicara.","Sering izin tidak masuk.","Menyelesaikan pekerjaan secara asal supaya cepat selesai, karena menurut Anda kualitas tidak terlalu diperhatikan atasan."],"s":[4,5,3,2,1],"w":["Mandiri.","Terbuka dan solutif.","Pasif.","Menghindar.","Menurunkan kualitas."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3199,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda melakukan kesalahan yang membuat kantor mengalami kerugian kecil. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengakui kesalahan kepada atasan, membantu memperbaiki dampaknya, dan mencegah hal serupa terulang.” Bertanggung jawab.\nPilihan terendah (nilai 1): “Menyalahkan rekan lain.” Tidak jujur.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Mengakui kesalahan kepada atasan, membantu memperbaiki dampaknya, dan mencegah hal serupa terulang.","Menyalahkan rekan lain.","Menyalahkan keadaan.","Memperbaiki dampaknya diam-diam tanpa melapor, karena kerugiannya kecil dan Anda tidak ingin membebani atasan dengan masalah yang sudah selesai.","Menunggu sampai ketahuan."],"s":[5,1,2,4,3],"w":["Bertanggung jawab.","Tidak jujur.","Menghindar.","Bertanggung jawab, tidak transparan.","Pasif."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3200,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda mendapat promosi, tetapi sebagian rekan meragukan kemampuan Anda. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Membuktikan kemampuan lewat kinerja dan mengajak rekan bekerja sama dengan baik.” Profesional.\nPilihan terendah (nilai 1): “Memberi tugas berat kepada rekan yang meragukan Anda supaya mereka tahu siapa yang sekarang menjadi atasan di unit itu.” Menyalahgunakan jabatan.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Membuktikan kemampuan lewat kinerja dan mengajak rekan bekerja sama dengan baik.","Menghindari rekan yang meragukan.","Menunggu keraguan reda sendiri.","Memberi tugas berat kepada rekan yang meragukan Anda supaya mereka tahu siapa yang sekarang menjadi atasan di unit itu.","Fokus bekerja tanpa menanggapi keraguan."],"s":[5,2,3,1,4],"w":["Profesional.","Menghindar.","Pasif.","Menyalahgunakan jabatan.","Fokus."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3201,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda diminta menjadi narasumber di luar kantor dengan honor, pada jam kerja. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengikuti aturan izin dan ketentuan honor yang berlaku, serta memastikan tugas kantor tetap berjalan.” Patuh aturan.\nPilihan terendah (nilai 1): “Menerima honor dan tetap mengisi kehadiran penuh di kantor seolah-olah bekerja seharian.” Tidak jujur.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Menerima undangan tanpa izin karena hanya dua jam.","Menolak tanpa mempertimbangkan.","Meminta izin atasan lebih dulu.","Mengikuti aturan izin dan ketentuan honor yang berlaku, serta memastikan tugas kantor tetap berjalan.","Menerima honor dan tetap mengisi kehadiran penuh di kantor seolah-olah bekerja seharian."],"s":[3,2,4,5,1],"w":["Kurang tertib.","Menutup peluang.","Tepat.","Patuh aturan.","Tidak jujur."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3202,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda menerima tugas yang tenggatnya tidak realistis. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menyampaikan perkiraan waktu yang realistis kepada atasan disertai alasan, dan mengusulkan prioritas.” Terbuka dan solutif.\nPilihan terendah (nilai 1): “Menyerahkan pekerjaan asal jadi tepat pada tenggat.” Menurunkan kualitas.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Mengerjakan sebisanya tanpa bicara.","Menyampaikan perkiraan waktu yang realistis kepada atasan disertai alasan, dan mengusulkan prioritas.","Menerima tugas itu lalu bekerja lembur setiap malam tanpa membicarakan tenggatnya, karena tidak ingin dianggap tidak mampu oleh atasan.","Menunda dan berharap tenggat diundur.","Menyerahkan pekerjaan asal jadi tepat pada tenggat."],"s":[3,5,4,2,1],"w":["Pasif.","Terbuka dan solutif.","Berusaha, tetapi tidak terbuka.","Menghindar.","Menurunkan kualitas."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3203,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Seorang rekan meminta Anda menyelesaikan pekerjaannya dengan imbalan uang. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menolak dan mendorongnya menyelesaikan pekerjaannya sendiri, sambil menawarkan bantuan berupa penjelasan bila perlu.” Menjaga integritas dan tetap membantu.\nPilihan terendah (nilai 1): “Menerima tawaran itu karena pekerjaannya mudah dan uangnya bisa menambah penghasilan.” Tidak etis.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Menolak dan mendorongnya menyelesaikan pekerjaannya sendiri, sambil menawarkan bantuan berupa penjelasan bila perlu.","Menghindarinya.","Menerima tawaran itu karena pekerjaannya mudah dan uangnya bisa menambah penghasilan.","Menolak permintaannya.","Menunda jawaban."],"s":[5,2,1,4,3],"w":["Menjaga integritas dan tetap membantu.","Menghindar.","Tidak etis.","Tepat.","Ragu."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3204,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda menemukan cara kerja baru yang lebih efisien, tetapi rekan senior menolaknya. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menunjukkan bukti manfaatnya lewat uji coba kecil dan mengajak rekan senior mengevaluasi hasilnya bersama.” Meyakinkan dengan bukti.\nPilihan terendah (nilai 1): “Menerapkan cara baru diam-diam tanpa memberi tahu siapa pun, sehingga data rekan dan data Anda menjadi tidak sinkron.” Tidak koordinatif.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Menerapkan cara baru diam-diam tanpa memberi tahu siapa pun, sehingga data rekan dan data Anda menjadi tidak sinkron.","Tetap memakai cara lama.","Menyerah karena tidak ingin berselisih.","Menunjukkan bukti manfaatnya lewat uji coba kecil dan mengajak rekan senior mengevaluasi hasilnya bersama.","Menyampaikan ide itu kepada atasan."],"s":[1,3,2,5,4],"w":["Tidak koordinatif.","Pasif.","Menghindar.","Meyakinkan dengan bukti.","Inisiatif."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3205,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda dimutasi ke daerah terpencil. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menerima tugas itu, mempersiapkan diri, dan menjalankannya dengan sungguh-sungguh.” Loyal dan berdedikasi.\nPilihan terendah (nilai 1): “Meminta bantuan kenalan pejabat supaya dipindahkan ke kota, karena menurut Anda kemampuan Anda lebih berguna di kantor pusat.” Nepotisme.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Menerima tugas itu, mempersiapkan diri, dan menjalankannya dengan sungguh-sungguh.","Menerima tugas sambil berharap bisa segera dipindahkan kembali.","Menunda keberangkatan sampai ada kepastian fasilitas.","Mencari cara supaya mutasinya dibatalkan.","Meminta bantuan kenalan pejabat supaya dipindahkan ke kota, karena menurut Anda kemampuan Anda lebih berguna di kantor pusat."],"s":[5,4,3,2,1],"w":["Loyal dan berdedikasi.","Menerima, kurang semangat.","Menunda.","Menghindar.","Nepotisme."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3206,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Atasan meminta Anda menandatangani berita acara pemeriksaan barang yang belum Anda periksa. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Memeriksa barang itu lebih dulu, lalu menandatangani sesuai hasil pemeriksaan.” Cermat dan jujur.\nPilihan terendah (nilai 1): “Langsung menandatangani karena atasan menjamin barangnya sesuai dan vendornya sudah biasa bekerja sama dengan kantor.” Tidak jujur.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Memeriksa barang itu lebih dulu, lalu menandatangani sesuai hasil pemeriksaan.","Menolak menandatangani sebelum memeriksa.","Langsung menandatangani karena atasan menjamin barangnya sesuai dan vendornya sudah biasa bekerja sama dengan kantor.","Menunda tanpa penjelasan.","Menandatangani dengan catatan belum diperiksa."],"s":[5,4,1,2,3],"w":["Cermat dan jujur.","Tegas.","Tidak jujur.","Menghindar.","Kurang tegas."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3207,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda diundang ke pesta pernikahan anak vendor yang sedang bekerja sama dengan kantor Anda. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mempertimbangkan risiko konflik kepentingan, tidak menerima pemberian apa pun, dan berkonsultasi dengan unit pengendali gratifikasi bila ragu.” Menjaga integritas.\nPilihan terendah (nilai 1): “Hadir dan menerima suvenir berharga yang dibagikan khusus untuk pegawai instansi Anda.” Gratifikasi.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Tidak hadir tanpa kabar.","Hadir sebentar tanpa membawa pulang suvenir mahal.","Hadir dan menerima suvenir berharga yang dibagikan khusus untuk pegawai instansi Anda.","Mempertimbangkan risiko konflik kepentingan, tidak menerima pemberian apa pun, dan berkonsultasi dengan unit pengendali gratifikasi bila ragu.","Hadir seperti biasa."],"s":[2,4,1,5,3],"w":["Kurang sopan.","Hati-hati.","Gratifikasi.","Menjaga integritas.","Kurang hati-hati."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3208,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda melihat unggahan di media sosial yang menjelek-jelekkan instansi Anda. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mencatat informasinya dan menyampaikannya kepada humas supaya ditanggapi dengan klarifikasi resmi bila perlu.” Tertib dan profesional.\nPilihan terendah (nilai 1): “Membalas unggahan itu dengan akun pribadi secara emosional dan mengajak rekan-rekan menyerang akun pengunggahnya bersama-sama.” Tidak profesional.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Mencatat informasinya dan menyampaikannya kepada humas supaya ditanggapi dengan klarifikasi resmi bila perlu.","Menghindari membuka media sosial.","Membalas unggahan itu dengan akun pribadi secara emosional dan mengajak rekan-rekan menyerang akun pengunggahnya bersama-sama.","Ikut membaca komentar-komentarnya.","Mengabaikannya karena belum tentu benar."],"s":[5,2,1,3,4],"w":["Tertib dan profesional.","Menghindar.","Tidak profesional.","Pasif.","Tenang, tanpa tindak lanjut."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3209,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda memiliki usaha sampingan, dan pelanggan sering menghubungi Anda saat jam kerja. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menetapkan jam layanan usaha di luar jam kerja dan memberi tahu pelanggan.” Memisahkan urusan pribadi dan dinas.\nPilihan terendah (nilai 1): “Melayani pelanggan di jam kerja memakai fasilitas kantor karena pekerjaan kantor sedang tidak terlalu banyak.” Penyalahgunaan waktu dan fasilitas.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Membalas sesekali saat sedang bekerja.","Membalas pesan pelanggan hanya saat istirahat.","Mematikan ponsel sepanjang hari, termasuk untuk urusan kantor.","Melayani pelanggan di jam kerja memakai fasilitas kantor karena pekerjaan kantor sedang tidak terlalu banyak.","Menetapkan jam layanan usaha di luar jam kerja dan memberi tahu pelanggan."],"s":[3,4,2,1,5],"w":["Mengganggu kerja.","Cukup tertib.","Menghambat komunikasi kerja.","Penyalahgunaan waktu dan fasilitas.","Memisahkan urusan pribadi dan dinas."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3210,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Seorang rekan mengajak bermain gim daring di jam kerja karena pekerjaan sedang sepi. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menolak dan memakai waktu luang untuk menyelesaikan pekerjaan lain atau belajar hal yang menunjang tugas.” Disiplin dan produktif.\nPilihan terendah (nilai 1): “Ikut bermain sampai jam pulang karena atasan sedang tidak ada dan semua pekerjaan hari itu sudah dianggap selesai.” Melanggar disiplin.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Ikut bermain sampai jam pulang karena atasan sedang tidak ada dan semua pekerjaan hari itu sudah dianggap selesai.","Menolak ajakannya.","Menolak dan memakai waktu luang untuk menyelesaikan pekerjaan lain atau belajar hal yang menunjang tugas.","Menghindari rekan itu.","Ikut sebentar."],"s":[1,4,5,2,3],"w":["Melanggar disiplin.","Disiplin.","Disiplin dan produktif.","Menghindar.","Kurang disiplin."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3211,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda ditegur karena pakaian dinas Anda tidak sesuai ketentuan. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menerima teguran dengan baik dan segera menyesuaikan pakaian dengan ketentuan.” Disiplin.\nPilihan terendah (nilai 1): “Mengabaikan teguran itu karena menurut Anda pakaian tidak berpengaruh pada kualitas kerja dan aturannya terlalu kaku.” Tidak disiplin.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Menjelaskan alasan tanpa berubah.","Menghindari bertemu yang menegur.","Menyesuaikan pakaian mulai besok.","Mengabaikan teguran itu karena menurut Anda pakaian tidak berpengaruh pada kualitas kerja dan aturannya terlalu kaku.","Menerima teguran dengan baik dan segera menyesuaikan pakaian dengan ketentuan."],"s":[3,2,4,1,5],"w":["Membela diri.","Menghindar.","Patuh.","Tidak disiplin.","Disiplin."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3212,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda menemukan kesalahan dalam keputusan atasan yang sudah diumumkan. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menyampaikan temuan itu kepada atasan secara pribadi dengan data, sehingga keputusan bisa diperbaiki.” Jujur dan santun.\nPilihan terendah (nilai 1): “Menyebarkan kesalahan itu kepada rekan-rekan untuk menjatuhkan atasan.” Tidak etis.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Menunggu orang lain yang menyampaikan.","Menuliskan catatan koreksi dan menitipkannya kepada sekretaris atasan untuk dibaca kapan sempat.","Menyampaikan temuan itu kepada atasan secara pribadi dengan data, sehingga keputusan bisa diperbaiki.","Membiarkannya.","Menyebarkan kesalahan itu kepada rekan-rekan untuk menjatuhkan atasan."],"s":[2,4,5,3,1],"w":["Menghindar.","Jujur, kurang cepat.","Jujur dan santun.","Pasif.","Tidak etis."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3213,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Pelatihan yang Anda ikuti mewajibkan tugas akhir, tetapi Anda sedang sibuk. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengatur waktu untuk menyelesaikan tugas akhir dengan sungguh-sungguh sesuai tenggat.” Bertanggung jawab.\nPilihan terendah (nilai 1): “Meminta orang lain mengerjakan tugas akhir itu dengan imbalan, karena isi pelatihannya toh sudah Anda pahami.” Tidak jujur.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Mengatur waktu untuk menyelesaikan tugas akhir dengan sungguh-sungguh sesuai tenggat.","Meminta perpanjangan waktu.","Meminta orang lain mengerjakan tugas akhir itu dengan imbalan, karena isi pelatihannya toh sudah Anda pahami.","Mengerjakan tugas akhir seadanya supaya tetap selesai tepat waktu.","Tidak mengumpulkan tugas."],"s":[5,3,1,4,2],"w":["Bertanggung jawab.","Menunda.","Tidak jujur.","Tepat waktu, kurang berkualitas.","Lalai."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3214,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda diberi kesempatan memimpin proyek untuk pertama kalinya. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menyusun rencana kerja, membagi tugas dengan jelas, berkomunikasi dengan tim, dan belajar dari pemimpin yang berpengalaman.” Siap memimpin.\nPilihan terendah (nilai 1): “Memanfaatkan posisi itu untuk memberi tugas berat kepada rekan yang tidak disukai.” Menyalahgunakan wewenang.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Menyusun rencana kerja, membagi tugas dengan jelas, berkomunikasi dengan tim, dan belajar dari pemimpin yang berpengalaman.","Memanfaatkan posisi itu untuk memberi tugas berat kepada rekan yang tidak disukai.","Menolak karena belum percaya diri.","Menerima tugas itu dan mengerjakan sebagian besar pekerjaan sendiri supaya hasilnya pasti sesuai harapan pimpinan.","Menunggu arahan rinci dari atasan."],"s":[5,1,2,4,3],"w":["Siap memimpin.","Menyalahgunakan wewenang.","Menghindar.","Bertanggung jawab, kurang memberdayakan tim.","Pasif."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3215,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda mengetahui seorang rekan memakai surat keterangan sakit palsu untuk tidak masuk kerja. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengingatkannya secara pribadi dan, bila berulang, melaporkannya kepada atasan sesuai prosedur.” Menjaga integritas.\nPilihan terendah (nilai 1): “Meminta alamat tempat ia membuat surat itu supaya bisa dipakai sendiri suatu hari nanti.” Ikut melanggar.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Meminta alamat tempat ia membuat surat itu supaya bisa dipakai sendiri suatu hari nanti.","Pura-pura tidak tahu.","Mengingatkannya secara pribadi.","Mengingatkannya secara pribadi dan, bila berulang, melaporkannya kepada atasan sesuai prosedur.","Membiarkannya karena bukan urusan Anda."],"s":[1,2,4,5,3],"w":["Ikut melanggar.","Menghindar.","Peduli.","Menjaga integritas.","Pasif."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3216,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Dalam rapat, pendapat Anda berbeda dengan pendapat sebagian besar peserta. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menyampaikan pendapat dengan data dan sopan, lalu menghormati keputusan yang disepakati.” Berani dan dewasa.\nPilihan terendah (nilai 1): “Bersikeras sampai rapat buntu dan menolak menjalankan keputusan bersama karena menurut Anda keputusannya jelas keliru.” Tidak menghormati keputusan.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Menyetujui tanpa bicara supaya tidak dianggap berbeda.","Bersikeras sampai rapat buntu dan menolak menjalankan keputusan bersama karena menurut Anda keputusannya jelas keliru.","Menyampaikan pendapat dengan data dan sopan, lalu menghormati keputusan yang disepakati.","Diam saja.","Menyampaikan pendapat secara singkat."],"s":[2,1,5,3,4],"w":["Menghindar.","Tidak menghormati keputusan.","Berani dan dewasa.","Pasif.","Berani."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3217,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Hasil evaluasi kinerja Anda lebih rendah dari yang Anda harapkan. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Meminta umpan balik rinci kepada atasan dan menyusun rencana perbaikan.” Mau belajar.\nPilihan terendah (nilai 1): “Mengeluhkan hasil evaluasi kepada rekan-rekan dan menuduh atasan pilih kasih tanpa bukti apa pun.” Tidak profesional.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Meminta umpan balik rinci kepada atasan dan menyusun rencana perbaikan.","Menerima tanpa tindak lanjut.","Mengeluhkan hasil evaluasi kepada rekan-rekan dan menuduh atasan pilih kasih tanpa bukti apa pun.","Menerima hasilnya dan berusaha lebih baik.","Menurunkan semangat kerja."],"s":[5,3,1,4,2],"w":["Mau belajar.","Pasif.","Tidak profesional.","Positif.","Menyerah."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3218,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda menerima informasi rahasia jabatan, dan seorang teman menanyakannya. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menolak membagikan informasi itu dengan sopan karena merupakan rahasia jabatan.” Menjaga kerahasiaan.\nPilihan terendah (nilai 1): “Membagikannya karena teman itu berjanji tidak akan menceritakannya kepada siapa pun.” Membocorkan rahasia.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Mengatakan tidak tahu.","Memberi petunjuk samar.","Menolak membagikan informasi itu dengan sopan karena merupakan rahasia jabatan.","Membagikannya karena teman itu berjanji tidak akan menceritakannya kepada siapa pun.","Menghindari teman itu."],"s":[4,3,5,1,2],"w":["Menjaga rahasia, kurang jujur.","Membocorkan sebagian.","Menjaga kerahasiaan.","Membocorkan rahasia.","Menghindar."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3219,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Atasan meminta Anda mengurus keperluan pribadinya di jam kerja. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menyampaikan dengan sopan bahwa jam kerja diperuntukkan bagi tugas kedinasan, sambil menawarkan bantuan di luar jam kerja bila memang perlu.” Santun dan menjaga profesionalitas.\nPilihan terendah (nilai 1): “Mengerjakannya memakai fasilitas dan anggaran kantor supaya cepat selesai dan atasan merasa terbantu.” Penyalahgunaan.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Menyampaikan dengan sopan bahwa jam kerja diperuntukkan bagi tugas kedinasan, sambil menawarkan bantuan di luar jam kerja bila memang perlu.","Mengerjakannya karena takut.","Menolak dengan sopan.","Mengerjakannya memakai fasilitas dan anggaran kantor supaya cepat selesai dan atasan merasa terbantu.","Mengulur waktu."],"s":[5,3,4,1,2],"w":["Santun dan menjaga profesionalitas.","Tidak tegas.","Tepat.","Penyalahgunaan.","Menghindar."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3220,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda diminta mengikuti seleksi jabatan, tetapi merasa belum siap. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menilai kesiapan secara jujur, mempersiapkan diri, dan mengikuti seleksi sebagai kesempatan belajar.” Berani berkembang.\nPilihan terendah (nilai 1): “Mencari bocoran soal seleksi.” Curang.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Menunda keputusan.","Menolak karena takut gagal.","Menilai kesiapan secara jujur, mempersiapkan diri, dan mengikuti seleksi sebagai kesempatan belajar.","Mencari bocoran soal seleksi.","Mengikuti seleksi tanpa persiapan khusus."],"s":[3,2,5,1,4],"w":["Ragu.","Menghindar.","Berani berkembang.","Curang.","Berani."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3221,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Seorang rekan memakai mobil dinas untuk mudik. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengingatkannya bahwa kendaraan dinas tidak boleh dipakai untuk keperluan pribadi, dan melaporkannya bila tetap dilakukan.” Menjaga aset negara.\nPilihan terendah (nilai 1): “Ikut menumpang mobil itu karena kampung halaman kalian searah dan perjalanan jadi lebih hemat.” Ikut melanggar.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Ikut menumpang mobil itu karena kampung halaman kalian searah dan perjalanan jadi lebih hemat.","Mengingatkannya bahwa kendaraan dinas tidak boleh dipakai untuk keperluan pribadi, dan melaporkannya bila tetap dilakukan.","Pura-pura tidak tahu.","Membiarkannya.","Mengingatkannya secara pribadi."],"s":[1,5,2,3,4],"w":["Ikut melanggar.","Menjaga aset negara.","Menghindar.","Pasif.","Peduli."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3222,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda mendapat tawaran kerja di swasta dengan gaji lebih tinggi saat proyek kantor belum selesai. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mempertimbangkan dengan matang dan, bila memutuskan pindah, mengikuti prosedur serta menyelesaikan serah terima tugas.” Bertanggung jawab.\nPilihan terendah (nilai 1): “Meninggalkan pekerjaan begitu saja tanpa serah terima karena gaji di tempat baru jauh lebih tinggi dan tawarannya tidak akan datang dua kali.” Tidak bertanggung jawab.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Meninggalkan pekerjaan begitu saja tanpa serah terima karena gaji di tempat baru jauh lebih tinggi dan tawarannya tidak akan datang dua kali.","Menyelesaikan proyek dulu sebelum memutuskan.","Menunda keputusan.","Mempertimbangkan dengan matang dan, bila memutuskan pindah, mengikuti prosedur serta menyelesaikan serah terima tugas.","Mengurangi kinerja sambil menunggu."],"s":[1,4,3,5,2],"w":["Tidak bertanggung jawab.","Bertanggung jawab.","Ragu.","Bertanggung jawab.","Tidak profesional."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3223,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda tidak setuju dengan pembagian tugas yang dibuat ketua tim. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menyampaikan keberatan dengan alasan yang jelas kepada ketua tim, lalu menjalankan keputusan akhirnya dengan baik.” Profesional.\nPilihan terendah (nilai 1): “Mengajak anggota lain menolak pembagian tugas itu bersama-sama supaya ketua tim terpaksa mengubahnya.” Menghasut.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Menjalankan tugas dengan setengah hati.","Mengajak anggota lain menolak pembagian tugas itu bersama-sama supaya ketua tim terpaksa mengubahnya.","Menyampaikan keberatan dengan alasan yang jelas kepada ketua tim, lalu menjalankan keputusan akhirnya dengan baik.","Menjalankan tugas sambil mencatat masukan untuk evaluasi.","Menunda pekerjaan."],"s":[3,1,5,4,2],"w":["Kurang profesional.","Menghasut.","Profesional.","Patuh.","Menghindar."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3224,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Laporan yang Anda susun ternyata memakai data lama. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Segera memperbarui data, memberi tahu pihak yang sudah menerima laporan, dan memeriksa ulang sumber data.” Bertanggung jawab.\nPilihan terendah (nilai 1): “Menyalahkan unit lain yang memberi data, padahal Anda yang tidak memeriksa tanggal datanya.” Tidak jujur.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Memperbaikinya untuk laporan berikutnya saja.","Segera memperbarui data, memberi tahu pihak yang sudah menerima laporan, dan memeriksa ulang sumber data.","Membiarkan karena selisihnya kecil.","Memperbarui data dan mengirim ulang laporan.","Menyalahkan unit lain yang memberi data, padahal Anda yang tidak memeriksa tanggal datanya."],"s":[3,5,2,4,1],"w":["Menunda.","Bertanggung jawab.","Abai.","Tepat.","Tidak jujur."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3225,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda mendapat tugas ke luar kota bersamaan dengan acara keluarga yang penting. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Membicarakan dengan atasan sejak awal untuk mencari jalan keluar, dan tetap mendahulukan tugas bila tidak ada pengganti.” Terbuka dan bertanggung jawab.\nPilihan terendah (nilai 1): “Tidak berangkat tanpa kabar.” Lalai.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Mengaku sakit supaya tidak berangkat.","Meminta rekan menggantikan tanpa memberi tahu atasan.","Berangkat tugas dan meminta maaf kepada keluarga.","Tidak berangkat tanpa kabar.","Membicarakan dengan atasan sejak awal untuk mencari jalan keluar, dan tetap mendahulukan tugas bila tidak ada pengganti."],"s":[2,3,4,1,5],"w":["Tidak jujur.","Tidak koordinatif.","Bertanggung jawab.","Lalai.","Terbuka dan bertanggung jawab."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3226,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Pimpinan meminta setiap pegawai menyumbang untuk acara pribadi pimpinan. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menyampaikan keberatan dengan sopan karena sumbangan seperti itu tidak boleh dipaksakan, dan menyarankan bentuk dukungan yang sukarela.” Menjaga integritas dengan santun.\nPilihan terendah (nilai 1): “Mengumpulkan sumbangan dari rekan-rekan dengan menyebut jumlah minimal supaya pimpinan senang dan Anda dianggap loyal.” Pungutan tidak sah.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Tidak ikut menyumbang.","Menyumbang karena takut.","Menghindari pembahasan.","Mengumpulkan sumbangan dari rekan-rekan dengan menyebut jumlah minimal supaya pimpinan senang dan Anda dianggap loyal.","Menyampaikan keberatan dengan sopan karena sumbangan seperti itu tidak boleh dipaksakan, dan menyarankan bentuk dukungan yang sukarela."],"s":[4,3,2,1,5],"w":["Tegas, kurang komunikatif.","Tidak tegas.","Menghindar.","Pungutan tidak sah.","Menjaga integritas dengan santun."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3227,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda mengetahui ada honor ganda untuk dua kegiatan yang waktunya bersamaan. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengambil honor hanya untuk kegiatan yang benar-benar diikuti dan mengembalikan kelebihannya.” Jujur.\nPilihan terendah (nilai 1): “Menerima keduanya karena sudah dibayarkan dan katanya semua panitia juga menerima dobel.” Tidak jujur.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Mengambil honor hanya untuk kegiatan yang benar-benar diikuti dan mengembalikan kelebihannya.","Menerima keduanya karena sudah dibayarkan dan katanya semua panitia juga menerima dobel.","Menanyakan aturan honor kepada bagian keuangan.","Menerima keduanya sambil menunggu ditegur.","Membiarkannya."],"s":[5,1,4,3,2],"w":["Jujur.","Tidak jujur.","Hati-hati.","Kurang jujur.","Abai."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3228,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Seorang rekan baru sering bertanya kepada Anda sehingga pekerjaan Anda tertunda. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menyediakan waktu khusus untuk menjawab pertanyaannya dan membuatkan catatan panduan supaya ia lebih mandiri.” Membantu sambil tetap produktif.\nPilihan terendah (nilai 1): “Menjawab dengan ketus supaya ia berhenti bertanya.” Tidak sopan.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Menyarankannya bertanya kepada orang lain.","Menyediakan waktu khusus untuk menjawab pertanyaannya dan membuatkan catatan panduan supaya ia lebih mandiri.","Menjawab dengan ketus supaya ia berhenti bertanya.","Menghindarinya.","Menjawab pertanyaannya setiap saat walaupun pekerjaan Anda sendiri terus tertunda sampai harus lembur."],"s":[3,5,1,2,4],"w":["Melempar.","Membantu sambil tetap produktif.","Tidak sopan.","Menghindar.","Membantu, mengorbankan tugas."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3229,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda diminta membuat laporan kegiatan yang sebenarnya tidak terlaksana. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menolak dan menyampaikan bahwa kegiatan itu tidak terlaksana, lalu mengusulkan tindak lanjut yang sesuai aturan.” Jujur dan akuntabel.\nPilihan terendah (nilai 1): “Membuat laporan lengkap dengan foto kegiatan lain supaya anggaran tetap bisa dipertanggungjawabkan.” Pemalsuan laporan.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Menolak dan menyampaikan bahwa kegiatan itu tidak terlaksana, lalu mengusulkan tindak lanjut yang sesuai aturan.","Membuat laporan dengan catatan samar.","Menunda sampai ada yang lain membuatnya.","Membuat laporan lengkap dengan foto kegiatan lain supaya anggaran tetap bisa dipertanggungjawabkan.","Menolak membuat laporan itu."],"s":[5,3,2,1,4],"w":["Jujur dan akuntabel.","Tidak tegas.","Menghindar.","Pemalsuan laporan.","Jujur."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3230,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda menemukan sisa barang persediaan kantor yang bisa dibawa pulang tanpa ketahuan. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengembalikan barang itu ke gudang dan mencatatnya.” Jujur.\nPilihan terendah (nilai 1): “Membawa pulang semuanya karena menurut Anda barang sisa itu toh akan dibuang dan tidak tercatat di inventaris mana pun.” Mengambil milik negara.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Memakainya untuk keperluan kantor saja.","Mengembalikan barang itu ke gudang dan mencatatnya.","Membiarkan barang itu di tempatnya.","Membawa pulang semuanya karena menurut Anda barang sisa itu toh akan dibuang dan tidak tercatat di inventaris mana pun.","Membawanya pulang sebagian kecil."],"s":[3,5,4,1,2],"w":["Wajar.","Jujur.","Jujur.","Mengambil milik negara.","Tidak jujur."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3231,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda ditugaskan mengawasi ujian dan melihat peserta yang merupakan kenalan Anda menyontek. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menindak sesuai tata tertib ujian tanpa membedakan, dan mencatatnya dalam berita acara.” Adil dan tegas.\nPilihan terendah (nilai 1): “Membantunya dengan memberi tahu jawaban karena kasihan dan ia sangat membutuhkan pekerjaan itu.” Curang.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Membantunya dengan memberi tahu jawaban karena kasihan dan ia sangat membutuhkan pekerjaan itu.","Meminta pengawas lain yang menangani.","Menindak sesuai tata tertib ujian tanpa membedakan, dan mencatatnya dalam berita acara.","Menegurnya dan memintanya berhenti.","Pura-pura tidak melihat."],"s":[1,2,5,4,3],"w":["Curang.","Menghindar.","Adil dan tegas.","Tegas, belum sesuai prosedur.","Tidak adil."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3232,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda diminta bekerja dari rumah, tetapi lingkungan rumah kurang mendukung. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menyiapkan tempat kerja seadanya yang tenang, mengatur jadwal, dan memberi tahu atasan kendala yang mungkin muncul.” Bertanggung jawab.\nPilihan terendah (nilai 1): “Mengaku bekerja padahal tidak, karena merasa tidak ada yang mengawasi selama bekerja dari rumah.” Tidak jujur.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Bekerja di kafe dengan memperhatikan keamanan data.","Sering tidak membalas pesan kantor.","Bekerja seadanya.","Mengaku bekerja padahal tidak, karena merasa tidak ada yang mengawasi selama bekerja dari rumah.","Menyiapkan tempat kerja seadanya yang tenang, mengatur jadwal, dan memberi tahu atasan kendala yang mungkin muncul."],"s":[4,2,3,1,5],"w":["Solutif, perlu hati-hati.","Lalai.","Pasif.","Tidak jujur.","Bertanggung jawab."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3233,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Atasan memberi target kinerja yang menurut Anda terlalu rendah. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengusulkan target yang lebih menantang disertai alasan, karena kinerja yang baik bermanfaat bagi layanan.” Proaktif.\nPilihan terendah (nilai 1): “Mengerjakan pekerjaan lain di luar tugas karena target sudah tercapai lebih awal dan sisa waktunya dianggap bebas.” Penyalahgunaan waktu.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Bekerja seadanya karena target mudah.","Mengusulkan target yang lebih menantang disertai alasan, karena kinerja yang baik bermanfaat bagi layanan.","Menerima tanpa komentar.","Menerima target itu dan berusaha melampauinya.","Mengerjakan pekerjaan lain di luar tugas karena target sudah tercapai lebih awal dan sisa waktunya dianggap bebas."],"s":[2,5,3,4,1],"w":["Menurunkan kualitas.","Proaktif.","Pasif.","Positif.","Penyalahgunaan waktu."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3234,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda melihat seorang pegawai rutin tidur di jam kerja. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengingatkannya secara pribadi dan, bila berulang, menyampaikan kepada atasan sesuai prosedur.” Menjaga disiplin.\nPilihan terendah (nilai 1): “Memotretnya lalu menyebarkan fotonya di grup kantor supaya ia malu dan berhenti melakukannya.” Mempermalukan.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Mengingatkannya secara pribadi.","Mengingatkannya secara pribadi dan, bila berulang, menyampaikan kepada atasan sesuai prosedur.","Memotretnya lalu menyebarkan fotonya di grup kantor supaya ia malu dan berhenti melakukannya.","Menghindari membahasnya.","Membiarkannya."],"s":[4,5,1,2,3],"w":["Peduli.","Menjaga disiplin.","Mempermalukan.","Menghindar.","Pasif."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3235,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Tugas Anda berubah karena adanya teknologi baru, dan Anda perlu keahlian baru. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mempelajari keahlian itu lewat pelatihan, latihan mandiri, dan bertanya kepada yang lebih ahli.” Terus belajar.\nPilihan terendah (nilai 1): “Menolak perubahan itu dan mengajak rekan lain menolak juga supaya teknologi baru tidak jadi dipakai di unit Anda.” Menghambat perubahan.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Meminta dipindahkan ke tugas lain.","Mempelajari keahlian itu lewat pelatihan, latihan mandiri, dan bertanya kepada yang lebih ahli.","Menunggu pelatihan resmi dari kantor.","Menolak perubahan itu dan mengajak rekan lain menolak juga supaya teknologi baru tidak jadi dipakai di unit Anda.","Bertahan dengan keahlian lama."],"s":[2,5,4,1,3],"w":["Menghindar.","Terus belajar.","Mau belajar, kurang inisiatif.","Menghambat perubahan.","Pasif."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3236,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda menerima surat panggilan sebagai saksi dalam kasus yang melibatkan rekan kerja. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Memenuhi panggilan dan memberikan keterangan yang jujur sesuai yang Anda ketahui.” Jujur dan taat hukum.\nPilihan terendah (nilai 1): “Mengubah keterangan supaya rekan itu terbebas karena ia sahabat Anda dan selama ini selalu membantu Anda.” Tidak jujur.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Memenuhi panggilan setelah berkonsultasi dengan bagian hukum kantor.","Mengubah keterangan supaya rekan itu terbebas karena ia sahabat Anda dan selama ini selalu membantu Anda.","Memenuhi panggilan tetapi memberi keterangan seminimal mungkin.","Mencari alasan untuk tidak hadir.","Memenuhi panggilan dan memberikan keterangan yang jujur sesuai yang Anda ketahui."],"s":[4,1,3,2,5],"w":["Hati-hati.","Tidak jujur.","Kurang jujur.","Menghindar.","Jujur dan taat hukum."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3237,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Seorang rekan meminta namanya dicantumkan sebagai anggota tim dalam laporan, padahal ia tidak ikut bekerja. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menolak dengan sopan dan menjelaskan bahwa laporan harus sesuai kontribusi nyata.” Jujur.\nPilihan terendah (nilai 1): “Mencantumkan namanya karena tidak enak menolak dan toh tidak ada yang dirugikan dari penambahan satu nama.” Tidak jujur.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Mengiyakan, tetapi tidak mencantumkannya.","Menyerahkan keputusan kepada ketua tim.","Menolak dengan sopan dan menjelaskan bahwa laporan harus sesuai kontribusi nyata.","Mencantumkan namanya karena tidak enak menolak dan toh tidak ada yang dirugikan dari penambahan satu nama.","Menolak permintaannya."],"s":[2,3,5,1,4],"w":["Tidak jujur.","Melempar.","Jujur.","Tidak jujur.","Jujur."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3238,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda menerima kritik dari warga melalui pengaduan resmi atas pekerjaan Anda. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menanggapi dengan terbuka, memeriksa fakta, memperbaiki yang keliru, dan menjelaskan hasilnya kepada warga.” Akuntabel.\nPilihan terendah (nilai 1): “Mencari tahu identitas pelapor untuk menegurnya.” Tidak etis.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Menunggu atasan memutuskan.","Memperbaiki pekerjaan tanpa menanggapi warga.","Menanggapi dengan terbuka, memeriksa fakta, memperbaiki yang keliru, dan menjelaskan hasilnya kepada warga.","Menganggap pengaduan itu tidak berdasar.","Mencari tahu identitas pelapor untuk menegurnya."],"s":[3,4,5,2,1],"w":["Pasif.","Bertanggung jawab, kurang komunikatif.","Akuntabel.","Membela diri.","Tidak etis."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3239,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Pihak luar meminta Anda menyampaikan data yang belum final kepada media. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menolak karena data belum final dan menjelaskan bahwa informasi resmi disampaikan oleh pejabat yang berwenang.” Tertib informasi.\nPilihan terendah (nilai 1): “Menyerahkan semua data karena pihak itu menawarkan imbalan dan berjanji tidak menyebut nama Anda.” Membocorkan data.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Menolak permintaan itu.","Menyerahkan semua data karena pihak itu menawarkan imbalan dan berjanji tidak menyebut nama Anda.","Menghindari permintaan itu.","Memberikan sebagian data.","Menolak karena data belum final dan menjelaskan bahwa informasi resmi disampaikan oleh pejabat yang berwenang."],"s":[4,1,2,3,5],"w":["Tepat.","Membocorkan data.","Menghindar.","Kurang tertib.","Tertib informasi."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3240,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda harus menyampaikan kabar tentang pemotongan anggaran kepada tim. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menyampaikannya dengan jujur dan jelas, menjelaskan dampaknya, dan mengajak tim menyusun prioritas bersama.” Terbuka dan memimpin.\nPilihan terendah (nilai 1): “Menyembunyikan kabar itu dan tetap menjanjikan kegiatan yang sudah tidak ada dananya.” Tidak jujur.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Menyampaikannya lewat pesan singkat di grup.","Menunggu atasan yang menyampaikan.","Menyampaikannya dengan jujur dan jelas, menjelaskan dampaknya, dan mengajak tim menyusun prioritas bersama.","Menyembunyikan kabar itu dan tetap menjanjikan kegiatan yang sudah tidak ada dananya.","Menunda kabar itu supaya tim tidak cemas."],"s":[4,3,5,1,2],"w":["Jujur, kurang personal.","Pasif.","Terbuka dan memimpin.","Tidak jujur.","Menghindar."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3241,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda menyadari salah satu kegiatan yang Anda rancang ternyata tidak bermanfaat bagi warga. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengevaluasinya secara jujur dan mengusulkan perbaikan atau penggantian kegiatan.” Akuntabel.\nPilihan terendah (nilai 1): “Melaporkan kegiatan itu sebagai berhasil supaya rencana Anda tidak dianggap gagal oleh pimpinan dan tim evaluasi.” Tidak jujur.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Tetap menjalankan kegiatan seperti biasa.","Menyampaikan evaluasi itu kepada atasan.","Tidak membahasnya.","Melaporkan kegiatan itu sebagai berhasil supaya rencana Anda tidak dianggap gagal oleh pimpinan dan tim evaluasi.","Mengevaluasinya secara jujur dan mengusulkan perbaikan atau penggantian kegiatan."],"s":[3,4,2,1,5],"w":["Pasif.","Jujur.","Menghindar.","Tidak jujur.","Akuntabel."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3242,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda mendapat tawaran beasiswa studi lanjut yang relevan dengan tugas Anda. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mendaftar sesuai prosedur kepegawaian, membicarakan pengaturan tugas dengan atasan, dan menyiapkan rencana studi.” Mengembangkan diri secara tertib.\nPilihan terendah (nilai 1): “Mendaftar diam-diam tanpa izin dan meninggalkan tugas begitu dinyatakan diterima.” Tidak bertanggung jawab.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Menolak karena tidak ingin repot.","Menunda keputusan sampai tahun depan.","Mendaftar diam-diam tanpa izin dan meninggalkan tugas begitu dinyatakan diterima.","Mendaftar setelah mendapat izin atasan.","Mendaftar sesuai prosedur kepegawaian, membicarakan pengaturan tugas dengan atasan, dan menyiapkan rencana studi."],"s":[2,3,1,4,5],"w":["Menutup peluang.","Ragu.","Tidak bertanggung jawab.","Tertib.","Mengembangkan diri secara tertib."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3243,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Seorang rekan memamerkan barang mewah yang diduga berasal dari sumber yang tidak wajar. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Tidak berprasangka tanpa bukti, tetapi bila ada indikasi kuat pelanggaran, menyampaikannya lewat saluran pengaduan resmi.” Objektif dan bertanggung jawab.\nPilihan terendah (nilai 1): “Menyebarkan dugaan bahwa ia korupsi kepada rekan-rekan lain tanpa bukti, karena menurut Anda gaya hidupnya terlalu mewah untuk ukuran pegawai.” Fitnah.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Menyebarkan dugaan bahwa ia korupsi kepada rekan-rekan lain tanpa bukti, karena menurut Anda gaya hidupnya terlalu mewah untuk ukuran pegawai.","Bersikap biasa dan tidak ikut menggunjing.","Tidak berprasangka tanpa bukti, tetapi bila ada indikasi kuat pelanggaran, menyampaikannya lewat saluran pengaduan resmi.","Membiarkannya.","Menjauhinya."],"s":[1,4,5,3,2],"w":["Fitnah.","Netral.","Objektif dan bertanggung jawab.","Pasif.","Menghindar."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3244,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Seorang kerabat meminta Anda mendukung salah satu partai politik di media sosial. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menolak dengan sopan karena ASN wajib menjaga netralitas, termasuk di media sosial.” Netral.\nPilihan terendah (nilai 1): “Mengunggah dukungan secara terbuka karena itu akun pribadi dan kerabat Anda sangat berharap dibantu.” Melanggar netralitas.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Menyukai unggahan partai itu sesekali.","Mengatakan akan mempertimbangkannya.","Mengunggah dukungan secara terbuka karena itu akun pribadi dan kerabat Anda sangat berharap dibantu.","Tidak menanggapi permintaannya.","Menolak dengan sopan karena ASN wajib menjaga netralitas, termasuk di media sosial."],"s":[3,2,1,4,5],"w":["Melanggar netralitas secara halus.","Tidak tegas.","Melanggar netralitas.","Netral, kurang komunikatif.","Netral."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3245,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda diangkat menjadi panitia pengadaan barang. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mempelajari aturan pengadaan, bekerja transparan, dan menghindari konflik kepentingan.” Profesional dan berintegritas.\nPilihan terendah (nilai 1): “Membocorkan harga perkiraan kepada vendor kenalan supaya pengadaan cepat selesai dan barangnya pasti sesuai selera kantor.” Kolusi.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Mempelajari aturan pengadaan, bekerja transparan, dan menghindari konflik kepentingan.","Mengikuti prosedur sesuai arahan.","Menghindari tugas penilaian.","Membocorkan harga perkiraan kepada vendor kenalan supaya pengadaan cepat selesai dan barangnya pasti sesuai selera kantor.","Mengikuti pendapat panitia senior."],"s":[5,4,2,1,3],"w":["Profesional dan berintegritas.","Patuh.","Menghindar.","Kolusi.","Pasif."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3246,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Ada kebiasaan pulang lebih awal di unit Anda saat atasan tidak ada. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Tetap bekerja sesuai jam kerja dan mengajak rekan menjaga disiplin.” Disiplin dan memberi contoh.\nPilihan terendah (nilai 1): “Pulang paling awal karena semua orang juga melakukannya dan atasan tidak pernah mempermasalahkan.” Melanggar disiplin.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Tetap bekerja sesuai jam kerja.","Pulang sedikit lebih awal.","Mengikuti kebiasaan itu sesekali.","Tetap bekerja sesuai jam kerja dan mengajak rekan menjaga disiplin.","Pulang paling awal karena semua orang juga melakukannya dan atasan tidak pernah mempermasalahkan."],"s":[4,3,2,5,1],"w":["Disiplin.","Kurang disiplin.","Tidak konsisten.","Disiplin dan memberi contoh.","Melanggar disiplin."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3247,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda diminta menggantikan atasan dalam rapat penting dengan persiapan yang singkat. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mempelajari bahan rapat secepatnya, menanyakan posisi atasan, dan mencatat hasil rapat untuk dilaporkan.” Siap dan bertanggung jawab.\nPilihan terendah (nilai 1): “Membuat keputusan atas nama atasan di luar arahan yang diberikan, karena merasa sudah paham kebijakan unit.” Melampaui wewenang.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Meminta rekan lain menggantikan.","Mempelajari bahan rapat secepatnya, menanyakan posisi atasan, dan mencatat hasil rapat untuk dilaporkan.","Hadir dan mencatat hasil rapat.","Hadir tanpa persiapan.","Membuat keputusan atas nama atasan di luar arahan yang diberikan, karena merasa sudah paham kebijakan unit."],"s":[2,5,4,3,1],"w":["Menghindar.","Siap dan bertanggung jawab.","Bertanggung jawab.","Kurang siap.","Melampaui wewenang."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3248,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda membuat janji kepada warga yang ternyata tidak bisa dipenuhi. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Segera menghubungi warga, meminta maaf, menjelaskan alasannya, dan menawarkan solusi lain.” Jujur dan bertanggung jawab.\nPilihan terendah (nilai 1): “Mengatakan bahwa janji itu tidak pernah Anda buat.” Tidak jujur.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Menghindari warga itu.","Segera menghubungi warga, meminta maaf, menjelaskan alasannya, dan menawarkan solusi lain.","Memberi tahu warga bahwa janji itu tidak bisa dipenuhi.","Mengatakan bahwa janji itu tidak pernah Anda buat.","Menunggu warga menanyakan."],"s":[2,5,4,1,3],"w":["Menghindar.","Jujur dan bertanggung jawab.","Jujur, kurang solutif.","Tidak jujur.","Pasif."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3249,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Hasil kerja tim Anda diklaim oleh unit lain dalam laporan pimpinan. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menyampaikan fakta kepada atasan dengan bukti kerja, lalu mengajak unit itu meluruskan laporan secara baik-baik.” Profesional dan jujur.\nPilihan terendah (nilai 1): “Membalas dengan mengklaim hasil kerja unit itu dalam laporan berikutnya supaya impas.” Tidak jujur.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Membiarkannya demi menjaga hubungan.","Menyampaikan keberatan kepada atasan.","Membalas dengan mengklaim hasil kerja unit itu dalam laporan berikutnya supaya impas.","Menyampaikan fakta kepada atasan dengan bukti kerja, lalu mengajak unit itu meluruskan laporan secara baik-baik.","Mengeluh kepada rekan tanpa bertindak."],"s":[3,4,1,5,2],"w":["Pasif.","Tepat.","Tidak jujur.","Profesional dan jujur.","Tidak solutif."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3250,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Seorang tetangga menawari Anda menjadi tim sukses calon anggota legislatif. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menolak dengan sopan karena ASN tidak boleh terlibat dalam kegiatan politik praktis.” Netral.\nPilihan terendah (nilai 1): “Menerima tawaran itu karena imbalannya besar dan menurut Anda tidak ada yang tahu bila Anda bekerja di balik layar.” Melanggar netralitas.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Menolak tawarannya.","Membantu diam-diam tanpa memakai nama.","Menjawab akan memikirkannya.","Menolak dengan sopan karena ASN tidak boleh terlibat dalam kegiatan politik praktis.","Menerima tawaran itu karena imbalannya besar dan menurut Anda tidak ada yang tahu bila Anda bekerja di balik layar."],"s":[4,3,2,5,1],"w":["Netral.","Melanggar netralitas.","Tidak tegas.","Netral.","Melanggar netralitas."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3251,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda mulai merasa bosan dengan pekerjaan rutin. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mencari cara memperbaiki proses kerja dan mengajukan diri untuk tugas pengembangan yang relevan.” Mengubah kebosanan menjadi inovasi.\nPilihan terendah (nilai 1): “Mengerjakan tugas secara asal karena merasa pekerjaan rutin tidak membutuhkan ketelitian dan tidak ada yang memeriksa.” Menurunkan kualitas.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Sering izin tidak masuk.","Mengerjakan tugas secara asal karena merasa pekerjaan rutin tidak membutuhkan ketelitian dan tidak ada yang memeriksa.","Mencari cara memperbaiki proses kerja dan mengajukan diri untuk tugas pengembangan yang relevan.","Mengikuti pelatihan untuk menambah wawasan.","Menjalani pekerjaan seadanya."],"s":[2,1,5,4,3],"w":["Menghindar.","Menurunkan kualitas.","Mengubah kebosanan menjadi inovasi.","Positif.","Pasif."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3252,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda menerima uang perjalanan dinas yang lebih besar dari biaya sebenarnya. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Melaporkan biaya sebenarnya dan mengembalikan kelebihannya sesuai prosedur.” Jujur dan akuntabel.\nPilihan terendah (nilai 1): “Memakai kelebihan uang itu untuk keperluan pribadi karena menurut Anda itu rezeki dari perjalanan yang melelahkan.” Tidak jujur.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Menyimpan kelebihannya sampai diminta.","Melaporkan biaya sebenarnya dan mengembalikan kelebihannya sesuai prosedur.","Memakai kelebihan uang itu untuk keperluan pribadi karena menurut Anda itu rezeki dari perjalanan yang melelahkan.","Menanyakan kepada bagian keuangan tentang kelebihan itu.","Membiarkannya."],"s":[3,5,1,4,2],"w":["Kurang jujur.","Jujur dan akuntabel.","Tidak jujur.","Hati-hati.","Abai."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3253,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Pimpinan meminta pekerjaan diselesaikan dengan kualitas seadanya supaya cepat. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menyampaikan risiko kualitas dengan sopan dan mengusulkan bagian yang bisa disederhanakan tanpa mengurangi mutu yang penting.” Seimbang dan bertanggung jawab.\nPilihan terendah (nilai 1): “Menyerahkan pekerjaan asal jadi lalu menyalahkan pimpinan bila nanti terjadi masalah.” Tidak bertanggung jawab.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Menyerahkan pekerjaan asal jadi lalu menyalahkan pimpinan bila nanti terjadi masalah.","Mengerjakan dengan lambat sebagai bentuk protes.","Menyelesaikan dengan cepat sambil tetap memeriksa bagian yang penting.","Menyampaikan risiko kualitas dengan sopan dan mengusulkan bagian yang bisa disederhanakan tanpa mengurangi mutu yang penting.","Mengikuti perintah apa adanya."],"s":[1,2,4,5,3],"w":["Tidak bertanggung jawab.","Tidak profesional.","Seimbang.","Seimbang dan bertanggung jawab.","Pasif."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3254,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Terbit peraturan baru yang mengubah cara kerja unit Anda. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mempelajari peraturan itu, mendiskusikan dampaknya dengan tim, dan menyesuaikan prosedur kerja.” Adaptif.\nPilihan terendah (nilai 1): “Mengabaikan peraturan baru karena menurut Anda cara lama sudah terbukti berhasil selama bertahun-tahun.” Melanggar aturan.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Mempelajari peraturan itu, mendiskusikan dampaknya dengan tim, dan menyesuaikan prosedur kerja.","Mempelajari peraturan itu sendiri.","Menunggu sosialisasi resmi.","Mengabaikan peraturan baru karena menurut Anda cara lama sudah terbukti berhasil selama bertahun-tahun.","Tetap memakai cara lama."],"s":[5,4,3,1,2],"w":["Adaptif.","Mau belajar.","Pasif.","Melanggar aturan.","Menolak perubahan."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3255,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda diminta menjelaskan pekerjaan Anda kepada auditor. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menyiapkan dokumen pendukung dan menjelaskan apa adanya dengan terbuka.” Akuntabel.\nPilihan terendah (nilai 1): “Menyembunyikan dokumen yang berpotensi menunjukkan kesalahan supaya hasil audit unit Anda terlihat bersih.” Tidak jujur.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Menjawab pertanyaan auditor secukupnya.","Menghindari bertemu auditor.","Menyembunyikan dokumen yang berpotensi menunjukkan kesalahan supaya hasil audit unit Anda terlihat bersih.","Menyiapkan dokumen pendukung dan menjelaskan apa adanya dengan terbuka.","Menunggu auditor meminta dokumen satu per satu."],"s":[4,2,1,5,3],"w":["Kooperatif.","Menghindar.","Tidak jujur.","Akuntabel.","Pasif."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3256,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Seorang rekan sering mencurahkan masalah pribadinya di jam kerja sehingga pekerjaannya terbengkalai. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mendengarkan dengan empati di waktu yang tepat, menyarankan bantuan konseling bila perlu, dan membantunya mengatur prioritas kerja.” Peduli dan profesional.\nPilihan terendah (nilai 1): “Menceritakan masalah pribadinya kepada rekan lain.” Tidak menjaga kepercayaan.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Menghindarinya.","Mendengarkannya kapan saja walaupun pekerjaan Anda dan pekerjaannya sama-sama tertunda.","Menceritakan masalah pribadinya kepada rekan lain.","Mendengarkannya di jam istirahat.","Mendengarkan dengan empati di waktu yang tepat, menyarankan bantuan konseling bila perlu, dan membantunya mengatur prioritas kerja."],"s":[2,3,1,4,5],"w":["Menghindar.","Peduli, mengorbankan tugas.","Tidak menjaga kepercayaan.","Peduli.","Peduli dan profesional."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3257,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda diminta memberi rekomendasi untuk seorang rekan yang menurut Anda kinerjanya kurang. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Memberi rekomendasi yang jujur sesuai kinerja yang Anda ketahui.” Jujur dan objektif.\nPilihan terendah (nilai 1): “Memberi rekomendasi yang sangat baik karena ia teman dekat dan Anda yakin ia akan berubah setelah naik jabatan.” Tidak objektif.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Memberi rekomendasi yang jujur sesuai kinerja yang Anda ketahui.","Memberi rekomendasi yang sangat baik karena ia teman dekat dan Anda yakin ia akan berubah setelah naik jabatan.","Memberi rekomendasi umum yang samar.","Menolak memberi rekomendasi dengan sopan.","Menunda sampai tenggat lewat."],"s":[5,1,3,4,2],"w":["Jujur dan objektif.","Tidak objektif.","Tidak tegas.","Jujur.","Menghindar."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3258,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda dipercaya memegang kas kegiatan. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mencatat setiap pemasukan dan pengeluaran dengan bukti, serta melaporkannya secara berkala.” Akuntabel.\nPilihan terendah (nilai 1): “Meminjam uang kas untuk keperluan pribadi dan berniat mengembalikannya sebelum laporan dibuat.” Penyalahgunaan.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Menunda pencatatan sampai akhir kegiatan.","Menyimpan bukti tanpa pencatatan.","Mencatat setiap pemasukan dan pengeluaran dengan bukti, serta melaporkannya secara berkala.","Meminjam uang kas untuk keperluan pribadi dan berniat mengembalikannya sebelum laporan dibuat.","Mencatat pengeluaran besar saja."],"s":[2,3,5,1,4],"w":["Menunda.","Kurang tertib.","Akuntabel.","Penyalahgunaan.","Kurang lengkap."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3259,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda sudah menyelesaikan tugas utama, tetapi ada pekerjaan unit lain yang tertunda. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menawarkan bantuan kepada unit itu setelah memberi tahu atasan.” Proaktif dan koordinatif.\nPilihan terendah (nilai 1): “Pulang lebih awal karena tugas Anda sudah selesai dan menurut Anda pekerjaan unit lain bukan tanggung jawab Anda sama sekali.” Melanggar disiplin.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Membantu bila diminta.","Pulang lebih awal karena tugas Anda sudah selesai dan menurut Anda pekerjaan unit lain bukan tanggung jawab Anda sama sekali.","Pura-pura sibuk.","Menunggu tugas baru.","Menawarkan bantuan kepada unit itu setelah memberi tahu atasan."],"s":[4,1,2,3,5],"w":["Bersedia.","Melanggar disiplin.","Tidak jujur.","Pasif.","Proaktif dan koordinatif."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3260,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda menerima instruksi yang kurang jelas dari atasan. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menanyakan bagian yang belum jelas kepada atasan sebelum mulai bekerja.” Mencegah salah kerja.\nPilihan terendah (nilai 1): “Mengerjakan sesuka hati lalu menyalahkan atasan bila hasilnya keliru.” Tidak bertanggung jawab.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Menunda sampai atasan bertanya.","Menanyakan bagian yang belum jelas kepada atasan sebelum mulai bekerja.","Bertanya kepada rekan yang mungkin tahu.","Mengerjakan sesuai tafsiran Anda, lalu menunjukkan hasilnya kepada atasan.","Mengerjakan sesuka hati lalu menyalahkan atasan bila hasilnya keliru."],"s":[2,5,3,4,1],"w":["Menunda.","Mencegah salah kerja.","Kurang tepat.","Inisiatif, berisiko salah.","Tidak bertanggung jawab."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3261,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda mendapat kritik bahwa surat dinas yang Anda buat banyak salah ketik. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Memperbaiki surat itu, memakai daftar periksa, dan membaca ulang sebelum mengirim surat berikutnya.” Belajar dari kesalahan.\nPilihan terendah (nilai 1): “Menyalahkan aplikasi pengolah kata yang menurut Anda sering mengubah kata secara otomatis.” Tidak bertanggung jawab.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Menganggap salah ketik itu sepele.","Meminta rekan memeriksa surat-surat berikutnya.","Memperbaiki surat itu.","Memperbaiki surat itu, memakai daftar periksa, dan membaca ulang sebelum mengirim surat berikutnya.","Menyalahkan aplikasi pengolah kata yang menurut Anda sering mengubah kata secara otomatis."],"s":[2,3,4,5,1],"w":["Abai.","Bergantung pada orang lain.","Bertanggung jawab.","Belajar dari kesalahan.","Tidak bertanggung jawab."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3262,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda menjadi saksi seorang pegawai memotong anggaran kegiatan warga untuk kepentingan pribadi. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Mengumpulkan informasi yang Anda ketahui dan melaporkannya lewat sistem pengaduan pelanggaran yang menjamin kerahasiaan pelapor.” Berani dan sesuai prosedur.\nPilihan terendah (nilai 1): “Meminta bagian dari potongan itu supaya Anda tidak melapor.” Pemerasan dan korupsi.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Mengumpulkan informasi yang Anda ketahui dan melaporkannya lewat sistem pengaduan pelanggaran yang menjamin kerahasiaan pelapor.","Melaporkannya kepada atasan langsung.","Menegurnya secara pribadi saja.","Diam karena takut.","Meminta bagian dari potongan itu supaya Anda tidak melapor."],"s":[5,4,3,2,1],"w":["Berani dan sesuai prosedur.","Tepat.","Tidak tuntas.","Menghindar.","Pemerasan dan korupsi."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."},{"i":3263,"k":"skd.tkp.profesionalisme","j":"situasi","v":2,"q":"Anda diminta mempresentasikan hasil kerja di depan pejabat tinggi. Sikap Anda adalah …","e":"Pilihan terbaik (nilai 5): “Menyiapkan materi yang ringkas dan berbasis data, berlatih, dan menyiapkan jawaban untuk pertanyaan sulit.” Siap dan profesional.\nPilihan terendah (nilai 1): “Melebih-lebihkan hasil kerja supaya terlihat mengesankan di depan pejabat dan tim mendapat apresiasi.” Tidak jujur.\nPrinsip aspek profesionalisme: Kerjakan tugas sesuai standar, tepat waktu, jujur, netral, dan bertanggung jawab; terus belajar dan pisahkan urusan pribadi dari urusan dinas.\nNilai tiap pilihan mengikuti rubrik Abdi: 5 proaktif dan tuntas sesuai aturan, 4 baik tetapi belum tuntas, 3 netral atau menunggu arahan, 2 menghindar atau menunda, 1 melanggar nilai ASN. Pilihan yang tidak dijawab bernilai 0. Kunci resmi BKN tidak dipublikasikan.\nCara cepat: Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi.","o":["Meminta rekan yang presentasi.","Menyiapkan materi yang ringkas dan berbasis data, berlatih, dan menyiapkan jawaban untuk pertanyaan sulit.","Menyiapkan materi dengan baik.","Melebih-lebihkan hasil kerja supaya terlihat mengesankan di depan pejabat dan tim mendapat apresiasi.","Membaca materi saat presentasi."],"s":[2,5,4,1,3],"w":["Menghindar.","Siap dan profesional.","Siap.","Tidak jujur.","Kurang siap."],"h":"Coret dulu pilihan yang melanggar aturan atau etika, lalu yang menghindar, menunda, atau melempar tugas. Dari sisanya, pilih yang langsung bertindak, sesuai aturan, dan menuntaskan masalah sampai ke akarnya. Kata kunci nilai tinggi: bertanggung jawab, jujur, tepat waktu, terus belajar, netral. Waspadai menunda, menutupi kesalahan, dan memakai jabatan untuk kepentingan pribadi."}];
